"use strict";

(function ($) {
  "use strict";

  $.fn.is_exist = function () {
    return this.length;
  };

  $(function () {
    var $window = $(window);

    $(".aximo-preloader-wrap").fadeOut(500);

    var $skillbar = $(".aximo-skillbar");
    if ($skillbar.is_exist()) {
      $skillbar.skillBars({
        from: 0,
        speed: 4000,
        interval: 100,
        decimals: 0
      });
    }

    $window.on("scroll", function () {
      if ($window.scrollTop() > 50) {
        $("#sticky-menu").addClass("sticky-menu");
      } else {
        $("#sticky-menu").removeClass("sticky-menu");
      }
    });

    $(".barger-menu").on("click", function (event) {
      $(".aximo-sidemenu-column, .offcanvas-overlay").addClass("active");
      event.preventDefault();
    });

    $(".aximo-sidemenu-close, .offcanvas-overlay").on("click", function () {
      $(".aximo-sidemenu-column, .offcanvas-overlay").removeClass("active");
    });

    var $counter = $("#aximo-counter");
    if ($counter.is_exist()) {
      var counterActivated = false;
      $window.on("scroll.counter", function () {
        var offset = $counter.offset().top - window.innerHeight;
        if (!counterActivated && $window.scrollTop() > offset) {
          $(".aximo-counter").each(function () {
            var $this = $(this);
            var countTo = Number($this.attr("data-percentage")) || 0;
            $({ countNum: Number($this.text()) || 0 }).animate({
              countNum: countTo
            }, {
              duration: 4000,
              easing: "swing",
              step: function (now) {
                $this.text(Math.floor(now));
              },
              complete: function () {
                $this.text(this.countNum);
              }
            });
          });
          counterActivated = true;
          $window.off("scroll.counter");
        }
      });
    }

    var $rotateTwo = $("#rotatetwo");
    if ($rotateTwo.is_exist()) {
      $window.on("scroll.rotate", function () {
        var right = 18 - $window.scrollTop() * 0.01;
        $rotateTwo.css("transform", "rotate(" + right + "deg)");
      });
    }

    new Swiper(".aximo-auto-slider", {
      spaceBetween: 0,
      centeredSlides: true,
      speed: 6000,
      autoplay: { delay: 0.5 },
      loop: true,
      slidesPerView: "auto",
      allowTouchMove: false,
      disableOnInteraction: true
    });

    new Swiper(".aximo-project-slider", {
      spaceBetween: 24,
      direction: "horizontal",
      mousewheel: {
        releaseOnEdges: true
      },
      pagination: {
        el: ".swiper-pagination",
        clickable: true
      },
      breakpoints: {
        640: { slidesPerView: 1 },
        900: { slidesPerView: 2 },
        1600: { slidesPerView: 3.5 }
      }
    });

    new Swiper(".aximo-project-slider2", {
      spaceBetween: 24,
      scrollbar: {
        el: ".swiper-scrollbar",
        draggable: true,
        clickable: false
      },
      breakpoints: {
        640: { slidesPerView: 1 },
        900: { slidesPerView: 2 },
        1600: { slidesPerView: 3 }
      }
    });

    new Swiper(".aximo-instagram-slider", {
      loop: true,
      breakpoints: {
        640: { slidesPerView: 2 },
        900: { slidesPerView: 3 },
        1200: {
          slidesPerView: 4,
          autoplay: { delay: 1 }
        },
        1400: { slidesPerView: 5 }
      }
    });

    new Swiper(".aximo-testimonial-slider", {
      slidesPerView: 1,
      pagination: {
        el: ".swiper-pagination",
        clickable: true
      }
    });

    var $videoInit = $(".video-init");
    if ($videoInit.is_exist()) {
      $videoInit.magnificPopup({
        type: "iframe",
        mainClass: "mfp-fade"
      });
    }

    var serviceRows = document.querySelectorAll(".aximo-service-increase-row");
    var serviceHoverInitialized = false;
    var activeImage = null;

    var initServiceHover = function () {
      if (serviceHoverInitialized || typeof gsap === "undefined" || !serviceRows.length) {
        return;
      }

      serviceHoverInitialized = true;
      gsap.set(".aximo-service-increase-row img.swipeimage", {
        yPercent: -50,
        xPercent: -50
      });

      serviceRows.forEach(function (row) {
        var image = row.querySelector("img.swipeimage");
        if (!image) return;

        var setX;
        var setY;
        var align = function (event) {
          if (setX && setY) {
            setX(event.clientX);
            setY(event.clientY);
          }
        };

        var fade = gsap.to(image, {
          autoAlpha: 1,
          ease: "none",
          paused: true,
          onReverseComplete: function () {
            document.removeEventListener("mousemove", align);
          }
        });

        row.addEventListener("mouseenter", function (event) {
          fade.play();
          document.addEventListener("mousemove", align);

          if (activeImage) {
            gsap.set(image, {
              x: gsap.getProperty(activeImage, "x"),
              y: gsap.getProperty(activeImage, "y")
            });
          }

          activeImage = image;
          setX = gsap.quickTo(image, "x", { duration: 0.6, ease: "power3" });
          setY = gsap.quickTo(image, "y", { duration: 0.6, ease: "power3" });
          align(event);
        });

        row.addEventListener("mouseleave", function () {
          fade.reverse();
        });
      });
    };

    var loadGsapAndInit = function () {
      if (serviceHoverInitialized || !serviceRows.length) {
        return;
      }

      if (typeof gsap !== "undefined") {
        initServiceHover();
        return;
      }

      var existing = document.querySelector('script[src="assets/js/gsap.min.js"]');
      if (existing) {
        existing.addEventListener("load", initServiceHover, { once: true });
        return;
      }

      var script = document.createElement("script");
      script.src = "assets/js/gsap.min.js";
      script.async = true;
      script.onload = initServiceHover;
      script.onerror = function (error) {
        console.warn("[GSAP] Failed to load", error);
      };
      document.head.appendChild(script);
    };

    if (serviceRows.length) {
      if ("IntersectionObserver" in window) {
        var observer = new IntersectionObserver(function (entries, obs) {
          entries.forEach(function (entry) {
            if (entry.isIntersecting) {
              obs.disconnect();
              loadGsapAndInit();
            }
          });
        }, { rootMargin: "0px 0px 200px 0px" });
        observer.observe(serviceRows[0]);
      } else {
        setTimeout(loadGsapAndInit, 0);
      }
    }

    $("#l5-pricing-btn .toggle-btn").on("click", function (event) {
      var $target = $(event.target);
      $target.toggleClass("clicked");
      var $wrapper = $target.parent().parent();
      if ($wrapper.hasClass("monthly-active")) {
        $wrapper.removeClass("monthly-active").addClass("yearly-active");
      } else {
        $wrapper.removeClass("yearly-active").addClass("monthly-active");
      }
    });

    $("[data-pricing-trigger]").on("click", function (event) {
      var $target = $(event.target);
      $target.addClass("active").siblings().removeClass("active");
      var targetSelector = $target.attr("data-target");
      var $pricingWrapper = $(targetSelector);
      if ($pricingWrapper.attr("data-value-active") === "monthly") {
        $pricingWrapper.attr("data-value-active", "yearly");
      } else {
        $pricingWrapper.attr("data-value-active", "monthly");
      }
    });
  });

  $(window).on("resize", function () {});
  $(window).on("load", function () {});

  if ($("#map").is_exist()) {
    google.maps.event.addDomListener(window, "load", function () {
      var mapOptions = {
        zoom: 11,
        scrollwheel: false,
        navigationControl: false,
        mapTypeControl: false,
        scaleControl: false,
        draggable: true,
        disableDefaultUI: true,
        center: new google.maps.LatLng(40.67, -73.94),
        styles: [
          { featureType: "landscape.man_made", elementType: "geometry", stylers: [{ color: "#f7f1df" }] },
          { featureType: "landscape.natural", elementType: "geometry", stylers: [{ color: "#d0e3b4" }] },
          { featureType: "landscape.natural.terrain", elementType: "geometry", stylers: [{ visibility: "off" }] },
          { featureType: "poi", elementType: "labels", stylers: [{ visibility: "off" }] },
          { featureType: "poi.business", elementType: "all", stylers: [{ visibility: "off" }] },
          { featureType: "poi.medical", elementType: "geometry", stylers: [{ color: "#fbd3da" }] },
          { featureType: "poi.park", elementType: "geometry", stylers: [{ color: "#bde6ab" }] },
          { featureType: "road", elementType: "geometry.stroke", stylers: [{ visibility: "off" }] },
          { featureType: "road", elementType: "labels", stylers: [{ visibility: "off" }] },
          { featureType: "road.highway", elementType: "geometry.fill", stylers: [{ color: "#ffe15f" }] },
          { featureType: "road.highway", elementType: "geometry.stroke", stylers: [{ color: "#efd151" }] },
          { featureType: "road.arterial", elementType: "geometry.fill", stylers: [{ color: "#ffffff" }] },
          { featureType: "road.local", elementType: "geometry.fill", stylers: [{ color: "black" }] },
          { featureType: "transit.station.airport", elementType: "geometry.fill", stylers: [{ color: "#cfb2db" }] },
          { featureType: "water", elementType: "geometry", stylers: [{ color: "#a2daf2" }] }
        ]
      };

      var mapElement = document.getElementById("map");
      if (!mapElement) return;

      var map = new google.maps.Map(mapElement, mapOptions);
      var marker = new google.maps.Marker({
        position: new google.maps.LatLng(40.67, -73.94),
        map: map,
        title: "fugu"
      });

      var infoWindow = new google.maps.InfoWindow({
        content: '<div id="content"><div id="tpw"><h3>fugu</h3></div></div>',
        maxWidth: 280
      });

      marker.setAnimation(google.maps.Animation.BOUNCE);
      setTimeout(function () {
        marker.setAnimation(null);
      }, 750);

      google.maps.event.addListener(marker, "click", function () {
        infoWindow.open(map, marker);
      });
    });
  }

  new WOW({ mobile: false, tablet: false }).init();
})(jQuery);